/* M.U.S.E — Interactive 3D Systems Atlas
 * ----------------------------------------------------------------------------
 * An interactive, ultra-HD 3D model of M.U.S.E and all its systems, plus an
 * animated "first prompt -> fully built product" pipeline.
 *
 * Data-driven: every node and narration beat comes from architecture_data.js,
 * which is generated by scripts/diagrams/build_muse_flowchart.py — the same
 * single source that produces the architecture PDF — so this model reflects
 * repository changes whenever that generator is re-run.
 *
 * Renderer: three.js, vendored locally (no CDN, no build step). The orbit rig
 * is a self-contained, damped equivalent of OrbitControls (which ships only in
 * three's examples/), following the pattern already used by the cockpit
 * Observatory page in this repo.
 * ------------------------------------------------------------------------- */

import * as THREE from "./vendor/three.module.min.js";

const DATA = window.MUSE_ARCH || { planes: [], pipeline: [], stats: [] };
const $ = (s) => document.querySelector(s);
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const easeInOutCubic = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* ════════════════════════════════════════════════════════════════════════
 * Renderer / scene / camera
 * ════════════════════════════════════════════════════════════════════════ */
const canvas = $("#scene");
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: "high-performance" });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2.5)); // ultra-HD
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x05080f, 0.00075);

const camera = new THREE.PerspectiveCamera(52, window.innerWidth / window.innerHeight, 0.5, 6000);

scene.add(new THREE.AmbientLight(0x2a3a55, 1.25));
const keyLight = new THREE.PointLight(0x36e6f0, 1.1, 0, 1.4); keyLight.position.set(260, 520, 320); scene.add(keyLight);
const fillLight = new THREE.PointLight(0xa06bff, 1.0, 0, 1.4); fillLight.position.set(-320, -360, -260); scene.add(fillLight);
const rimLight = new THREE.PointLight(0xffb13d, 0.5, 0, 1.6); rimLight.position.set(0, -560, 240); scene.add(rimLight);
scene.add(new THREE.HemisphereLight(0x223a5a, 0x05070f, 0.6)); // soft natural fill

/* Procedural image-based lighting: a dark studio gradient with a few coloured
 * highlights, pre-filtered into an environment map so the metallic nodes pick up
 * realistic reflections. Wrapped defensively — if PMREM is unavailable the scene
 * still renders perfectly without reflections. */
(function buildEnvironment() {
  try {
    const c = document.createElement("canvas"); c.width = 512; c.height = 256;
    const g = c.getContext("2d");
    const base = g.createLinearGradient(0, 0, 0, 256);
    base.addColorStop(0, "#0c1838"); base.addColorStop(0.5, "#0a1020"); base.addColorStop(1, "#04060d");
    g.fillStyle = base; g.fillRect(0, 0, 512, 256);
    for (const [x, y, r, col] of [
      [120, 80, 110, "rgba(54,230,240,0.55)"],
      [380, 60, 120, "rgba(160,107,255,0.50)"],
      [260, 200, 90, "rgba(47,208,122,0.40)"],
      [450, 180, 80, "rgba(255,177,61,0.30)"],
    ]) {
      const rg = g.createRadialGradient(x, y, 0, x, y, r);
      rg.addColorStop(0, col); rg.addColorStop(1, "rgba(0,0,0,0)");
      g.fillStyle = rg; g.fillRect(0, 0, 512, 256);
    }
    const tex = new THREE.CanvasTexture(c);
    tex.mapping = THREE.EquirectangularReflectionMapping;
    tex.colorSpace = THREE.SRGBColorSpace;
    const pmrem = new THREE.PMREMGenerator(renderer);
    pmrem.compileEquirectangularShader();
    scene.environment = pmrem.fromEquirectangular(tex).texture;
    pmrem.dispose(); tex.dispose();
  } catch (_e) {
    /* no IBL — still looks great with the lights + emissive glow */
  }
})();

/* ════════════════════════════════════════════════════════════════════════
 * Texture + sprite helpers
 * ════════════════════════════════════════════════════════════════════════ */
function glowTexture() {
  const c = document.createElement("canvas"); c.width = c.height = 128;
  const g = c.getContext("2d");
  const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, "rgba(255,255,255,1)");
  grad.addColorStop(0.25, "rgba(255,255,255,0.85)");
  grad.addColorStop(0.55, "rgba(255,255,255,0.25)");
  grad.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grad; g.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}
const GLOW = glowTexture();

function makeGlow(color, size, opacity) {
  const m = new THREE.SpriteMaterial({ map: GLOW, color, transparent: true, opacity: opacity ?? 0.55,
    blending: THREE.AdditiveBlending, depthWrite: false });
  const s = new THREE.Sprite(m); s.scale.set(size, size, 1); return s;
}

function makeLabel(text, opts = {}) {
  const fs = opts.fs || 44;
  const pad = opts.pad ?? 14;
  const weight = opts.weight || 700;
  const color = opts.color || "#eef3ff";
  const font = `${weight} ${fs}px -apple-system, "Segoe UI", Inter, Roboto, Arial, sans-serif`;
  const mc = document.createElement("canvas"); const mg = mc.getContext("2d");
  mg.font = font; const tw = Math.ceil(mg.measureText(text).width);
  const dpr = 3; // crisp at 4K / high-DPI
  mc.width = (tw + pad * 2) * dpr; mc.height = (fs + pad * 2) * dpr;
  mg.scale(dpr, dpr);
  mg.font = font; mg.textBaseline = "middle"; mg.textAlign = "center";
  if (opts.bg) {
    mg.fillStyle = opts.bg;
    roundRect(mg, 1, 1, mc.width / dpr - 2, mc.height / dpr - 2, 9); mg.fill();
  }
  mg.fillStyle = color;
  mg.shadowColor = "rgba(0,0,0,0.85)"; mg.shadowBlur = 6;
  mg.fillText(text, mc.width / dpr / 2, mc.height / dpr / 2);
  const tex = new THREE.CanvasTexture(mc); tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 4;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: opts.depthTest ?? true });
  const sp = new THREE.Sprite(mat);
  const h = opts.worldH || 10;
  sp.scale.set(h * (mc.width / mc.height), h, 1);
  sp.userData.isLabel = true;
  return sp;
}
function roundRect(g, x, y, w, h, r) {
  g.beginPath();
  g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);
  g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();
}

/* ════════════════════════════════════════════════════════════════════════
 * Starfield + nebula backdrop
 * ════════════════════════════════════════════════════════════════════════ */
(function starfield() {
  const N = 2600; const pos = new Float32Array(N * 3);
  for (let i = 0; i < N; i++) {
    const r = 1400 + Math.random() * 2600;
    const th = Math.random() * Math.PI * 2; const ph = Math.acos(2 * Math.random() - 1);
    pos[i * 3] = r * Math.sin(ph) * Math.cos(th);
    pos[i * 3 + 1] = r * Math.cos(ph);
    pos[i * 3 + 2] = r * Math.sin(ph) * Math.sin(th);
  }
  const g = new THREE.BufferGeometry(); g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  scene.add(new THREE.Points(g, new THREE.PointsMaterial({ color: 0x4a5675, size: 2.2, sizeAttenuation: true, transparent: true, opacity: 0.7, depthWrite: false })));
  for (let i = 0; i < 3; i++) {
    const col = [0x163b4a, 0x2a1e52, 0x102e2a][i];
    const neb = makeGlow(col, 1700, 0.16);
    neb.position.set((i - 1) * 900, (i - 1) * 700, -1400 - i * 200);
    scene.add(neb);
  }
})();

/* ════════════════════════════════════════════════════════════════════════
 * Build the synaptic tower from the data
 * ════════════════════════════════════════════════════════════════════════ */
const planes = DATA.planes || [];
const N = planes.length;
const STEP = 82;
const topY = ((N - 1) / 2) * STEP;
const planeY = (i) => topY - i * STEP;

const root = new THREE.Group(); scene.add(root);
const nodeMeshes = [];           // raycast targets
const planeRecords = [];         // per-plane handles for highlight/focus
const labelSprites = [];         // togglable labels

// central spine
const towerH = (N - 1) * STEP + 220;
const spineMat = new THREE.MeshBasicMaterial({ color: 0x5fb6ff });
const spine = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 2.2, towerH, 20, 1, true), spineMat);
spine.material.transparent = true; spine.material.opacity = 0.5;
root.add(spine);
const spineGlow = new THREE.Mesh(
  new THREE.CylinderGeometry(7, 7, towerH, 20, 1, true),
  new THREE.MeshBasicMaterial({ color: 0x3a7bd6, transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
);
root.add(spineGlow);

// flowing particles along the spine
const FLOW_N = 220;
const flowGeo = new THREE.BufferGeometry();
const flowPos = new Float32Array(FLOW_N * 3);
const flowSeed = new Float32Array(FLOW_N);
for (let i = 0; i < FLOW_N; i++) {
  flowSeed[i] = Math.random();
  flowPos[i * 3] = (Math.random() - 0.5) * 3;
  flowPos[i * 3 + 1] = (Math.random() - 0.5) * towerH;
  flowPos[i * 3 + 2] = (Math.random() - 0.5) * 3;
}
flowGeo.setAttribute("position", new THREE.BufferAttribute(flowPos, 3));
const flow = new THREE.Points(flowGeo, new THREE.PointsMaterial({ color: 0x8fe8ff, size: 3.2, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }));
root.add(flow);

const ICO = new THREE.IcosahedronGeometry(1, 3); // smoother spheres for a polished look

function buildPlane(p, i) {
  const accent = new THREE.Color(p.accent || "#36e6f0");
  const accent2 = new THREE.Color(p.accent2 || p.accent || "#a06bff");
  const y = planeY(i);
  const cards = p.cards || [];
  const m = cards.length;
  const ringR = 96 + Math.max(0, m - 3) * 9;
  const phase = i * 0.62;

  const group = new THREE.Group(); group.position.y = y; root.add(group);

  // platform ring
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(ringR, 0.9, 10, 120),
    new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.5 })
  );
  ring.rotation.x = Math.PI / 2; group.add(ring);
  const ringGlow = new THREE.Mesh(
    new THREE.TorusGeometry(ringR, 3.4, 10, 120),
    new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending, depthWrite: false })
  );
  ringGlow.rotation.x = Math.PI / 2; group.add(ringGlow);

  // hub
  const hub = new THREE.Mesh(ICO, new THREE.MeshStandardMaterial({ color: accent, emissive: accent, emissiveIntensity: 1.1, metalness: 0.62, roughness: 0.22, envMapIntensity: 1.0 }));
  hub.scale.setScalar(5); group.add(hub);
  const hubGlow = makeGlow(accent, 34, 0.45); group.add(hubGlow);

  // plane label (number + title) floating on the back edge
  const plabel = makeLabel(`${p.num} · ${p.title}`, { fs: 40, worldH: 15, weight: 800, color: "#ffffff", bg: "rgba(8,12,24,0.55)" });
  const la = phase + Math.PI * 0.5;
  plabel.position.set(Math.cos(la) * (ringR + 46), 14, Math.sin(la) * (ringR + 46));
  group.add(plabel); labelSprites.push(plabel);

  const nodeRecords = [];
  cards.forEach((card, k) => {
    const a = phase + (k / Math.max(1, m)) * Math.PI * 2;
    const x = Math.cos(a) * ringR, z = Math.sin(a) * ringR;

    const mat = new THREE.MeshStandardMaterial({ color: accent, emissive: accent, emissiveIntensity: 0.95, metalness: 0.68, roughness: 0.24, envMapIntensity: 0.9 });
    const node = new THREE.Mesh(ICO, mat);
    node.position.set(x, 0, z);
    node.scale.setScalar(card.gate ? 7.2 : 6.4);
    group.add(node);

    const glow = makeGlow(accent, card.gate ? 30 : 24, 0.5);
    glow.position.copy(node.position); group.add(glow);

    // owner-gated nodes wear a crimson halo ring
    if (card.gate) {
      const halo = new THREE.Mesh(
        new THREE.TorusGeometry(10.5, 0.7, 8, 40),
        new THREE.MeshBasicMaterial({ color: 0xff5a7a, transparent: true, opacity: 0.9 })
      );
      halo.position.copy(node.position);
      halo.lookAt(0, 0, 0);
      group.add(halo);
    }

    // spoke from hub to node
    const spoke = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), node.position.clone()]),
      new THREE.LineBasicMaterial({ color: accent, transparent: true, opacity: 0.22 })
    );
    group.add(spoke);

    // node label
    const nlabel = makeLabel(card.title, { fs: 30, worldH: 7.6, weight: 650, color: "#eaf1ff", bg: "rgba(7,11,22,0.55)" });
    nlabel.position.set(x, 13, z);
    group.add(nlabel); labelSprites.push(nlabel);

    node.userData = {
      card, planeIdx: i, planeTitle: `${p.num} · ${p.title}`,
      accent: p.accent, glow, mat, baseScale: node.scale.x, baseEmissive: 0.95, label: nlabel,
    };
    nodeMeshes.push(node);
    nodeRecords.push(node.userData);
  });

  planeRecords.push({ index: i, y, ringR, group, ring, ringGlow, hub, hubGlow, accent, accent2, nodes: nodeRecords, plabel, data: p });
}
planes.forEach(buildPlane);

/* MUSE core at the apex */
const coreY = topY + 96;
const coreGroup = new THREE.Group(); coreGroup.position.y = coreY; root.add(coreGroup);
const core = new THREE.Mesh(
  new THREE.IcosahedronGeometry(15, 4),
  new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xbfe4ff, emissiveIntensity: 1.25, metalness: 0.72, roughness: 0.1, envMapIntensity: 1.25 })
);
coreGroup.add(core);
coreGroup.add(makeGlow(0xbfe4ff, 130, 0.6));
const coreRing = new THREE.Mesh(
  new THREE.TorusGeometry(30, 1.4, 12, 120),
  new THREE.MeshBasicMaterial({ color: 0x8fd0ff, transparent: true, opacity: 0.8 })
);
coreRing.rotation.set(Math.PI / 2.6, 0.4, 0); coreGroup.add(coreRing);
const coreLabel = makeLabel("M.U.S.E — one mind", { fs: 40, worldH: 16, weight: 800, color: "#ffffff", bg: "rgba(8,12,24,0.5)" });
coreLabel.position.set(0, 40, 0); coreGroup.add(coreLabel); labelSprites.push(coreLabel);

/* "Fully built product" at the base (revealed by the pipeline) */
const prodY = planeY(N - 1) - 96;
const prodGroup = new THREE.Group(); prodGroup.position.y = prodY; prodGroup.visible = false; root.add(prodGroup);
const product = new THREE.Mesh(
  new THREE.OctahedronGeometry(20, 0),
  new THREE.MeshStandardMaterial({ color: 0x2fd07a, emissive: 0x2fd07a, emissiveIntensity: 1.2, metalness: 0.5, roughness: 0.2, flatShading: true })
);
prodGroup.add(product);
prodGroup.add(makeGlow(0x66ffb0, 150, 0.0)); // opacity animated on reveal
const prodLabel = makeLabel("✓ FULLY BUILT PRODUCT · shipped as a reviewed pull request", { fs: 34, worldH: 13, weight: 800, color: "#d6ffe9", bg: "rgba(8,24,16,0.6)" });
prodLabel.position.set(0, -42, 0); prodGroup.add(prodLabel);

/* the build packet (travels the pipeline) */
const packet = new THREE.Group(); root.add(packet);
const packetCore = new THREE.Mesh(ICO, new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffffff, emissiveIntensity: 2.0 }));
packetCore.scale.setScalar(5.5); packet.add(packetCore);
packet.add(makeGlow(0xffffff, 60, 0.85));
const packetLight = new THREE.PointLight(0xbfe4ff, 0, 360, 1.5); packet.add(packetLight);
packet.position.set(0, coreY, 0); packet.visible = false;
let packetGoalY = coreY;

/* ════════════════════════════════════════════════════════════════════════
 * Orbit rig (self-contained, damped — adapted from the cockpit Observatory)
 * ════════════════════════════════════════════════════════════════════════ */
class OrbitRig {
  constructor(dom) {
    this.target = new THREE.Vector3(0, 0, 0);
    this.goalTarget = this.target.clone();
    this.sph = new THREE.Spherical(880, 1.32, 0.62);
    this.goal = new THREE.Spherical(880, 1.32, 0.62);
    this.tween = null; this.lastInput = -1e9;
    this._p = new Map(); this._pinch = 0; this.dragMoved = 0;
    dom.style.touchAction = "none";
    dom.addEventListener("contextmenu", (e) => e.preventDefault());
    dom.addEventListener("pointerdown", (e) => {
      dom.setPointerCapture(e.pointerId);
      this._p.set(e.pointerId, { x: e.clientX, y: e.clientY, button: e.button, shift: e.shiftKey });
      if (this._p.size === 2) { const [a, b] = [...this._p.values()]; this._pinch = Math.hypot(a.x - b.x, a.y - b.y); }
      this.lastInput = performance.now(); this.dragMoved = 0;
    });
    dom.addEventListener("pointermove", (e) => {
      const p = this._p.get(e.pointerId); if (!p) return;
      const dx = e.clientX - p.x, dy = e.clientY - p.y; p.x = e.clientX; p.y = e.clientY;
      this.dragMoved += Math.abs(dx) + Math.abs(dy);
      this.lastInput = performance.now(); this.tween = null;
      if (this._p.size === 2) {
        const [a, b] = [...this._p.values()]; const d = Math.hypot(a.x - b.x, a.y - b.y);
        if (this._pinch > 0) this.dolly(this._pinch / Math.max(d, 1)); this._pinch = d; return;
      }
      if (p.button === 2 || p.shift) this.pan(dx, dy);
      else { this.goal.theta -= dx * 0.0050; this.goal.phi = clamp(this.goal.phi - dy * 0.0050, 0.10, Math.PI - 0.10); }
    });
    const up = (e) => { this._p.delete(e.pointerId); this._pinch = 0; };
    dom.addEventListener("pointerup", up); dom.addEventListener("pointercancel", up);
    dom.addEventListener("wheel", (e) => { e.preventDefault(); this.tween = null; this.lastInput = performance.now(); this.dolly(Math.exp(e.deltaY * 0.0010)); }, { passive: false });
  }
  dolly(f) { this.goal.radius = clamp(this.goal.radius * f, 70, 2600); }
  pan(dx, dy) {
    const scale = this.sph.radius * 0.0011;
    const right = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0);
    const upv = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 1);
    this.goalTarget.addScaledVector(right, -dx * scale).addScaledVector(upv, dy * scale);
  }
  flyTo(target, radius, phi, theta, dur) {
    this.tween = { t: 0, dur: dur || 1.0, fromT: this.target.clone(), toT: target.clone(),
      from: new THREE.Spherical(this.sph.radius, this.sph.phi, this.sph.theta),
      to: new THREE.Spherical(radius, phi, theta) };
    this.goalTarget.copy(target); this.goal.set(radius, phi, theta);
  }
  update(dt) {
    if (this.tween) {
      const tw = this.tween; tw.t = Math.min(1, tw.t + dt / tw.dur); const k = easeInOutCubic(tw.t);
      this.target.lerpVectors(tw.fromT, tw.toT, k);
      this.sph.radius = tw.from.radius + (tw.to.radius - tw.from.radius) * k;
      this.sph.phi = tw.from.phi + (tw.to.phi - tw.from.phi) * k;
      this.sph.theta = tw.from.theta + (tw.to.theta - tw.from.theta) * k;
      if (tw.t >= 1) this.tween = null;
    } else {
      const k = 1 - Math.exp(-dt * 8);
      this.target.lerp(this.goalTarget, k);
      this.sph.radius += (this.goal.radius - this.sph.radius) * k;
      this.sph.phi += (this.goal.phi - this.sph.phi) * k;
      this.sph.theta += (this.goal.theta - this.sph.theta) * k;
    }
    camera.position.setFromSpherical(this.sph).add(this.target);
    camera.lookAt(this.target);
  }
  idle() { return performance.now() - this.lastInput > 3500; }
}
const rig = new OrbitRig(canvas);

const VIEW_OVERVIEW = { target: new THREE.Vector3(0, 0, 0), radius: 980, phi: 1.30, theta: 0.62 };
function focusPlane(i) {
  const pr = planeRecords[i]; if (!pr) return;
  rig.flyTo(new THREE.Vector3(0, pr.y, 0), pr.ringR * 2.5 + 120, 1.18, pr.group.rotation.y + 0.5, 1.1);
  pulsePlane(i);
}
function resetView() { rig.flyTo(VIEW_OVERVIEW.target, VIEW_OVERVIEW.radius, VIEW_OVERVIEW.phi, VIEW_OVERVIEW.theta, 1.1); }

/* ════════════════════════════════════════════════════════════════════════
 * Highlight / pulse
 * ════════════════════════════════════════════════════════════════════════ */
const pulses = []; // {pr, t, dur}
function pulsePlane(i, dur = 1.6) { const pr = planeRecords[i]; if (pr) pulses.push({ pr, t: 0, dur }); }

/* ════════════════════════════════════════════════════════════════════════
 * Raycast hover + click
 * ════════════════════════════════════════════════════════════════════════ */
const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();
let hovered = null;
const tip = $("#tip");

function pointerNDC(e) {
  ndc.x = (e.clientX / window.innerWidth) * 2 - 1;
  ndc.y = -(e.clientY / window.innerHeight) * 2 + 1;
}
canvas.addEventListener("pointermove", (e) => {
  pointerNDC(e);
  ray.setFromCamera(ndc, camera);
  const hit = ray.intersectObjects(nodeMeshes, false)[0];
  const obj = hit ? hit.object : null;
  if (obj !== hovered) {
    hovered = obj;
    canvas.style.cursor = obj ? "pointer" : "default";
  }
  if (obj) {
    tip.style.display = "block";
    tip.style.left = e.clientX + "px"; tip.style.top = e.clientY + "px";
    tip.textContent = obj.userData.card.title;
  } else { tip.style.display = "none"; }
});
canvas.addEventListener("pointerup", () => {
  if (rig.dragMoved > 6) return;        // it was a drag, not a click
  if (hovered) openDetail(hovered.userData);
});

function openDetail(u) {
  const card = u.card;
  $("#detailKicker").textContent = u.planeTitle;
  $("#detailKicker").style.color = u.accent;
  $("#detailTitle").textContent = card.title;
  $("#detailDesc").textContent = card.desc;
  const chips = $("#detailChips"); chips.innerHTML = "";
  (card.tags || []).forEach((t) => { const s = document.createElement("span"); s.className = "chip"; s.textContent = t; chips.appendChild(s); });
  if (card.gate) { const g = document.createElement("span"); g.className = "gate"; g.textContent = "OWNER-GATED"; chips.appendChild(g); }
  $("#detail").classList.add("show");
  // fly to the node
  const world = new THREE.Vector3(); u.glow.getWorldPosition(world);
  rig.flyTo(world, 150, 1.12, Math.atan2(world.z, world.x) + 0.4, 0.9);
  pulsePlane(u.planeIdx, 1.4);
}
$("#detailClose").addEventListener("click", () => $("#detail").classList.remove("show"));

/* ════════════════════════════════════════════════════════════════════════
 * Legend (left)
 * ════════════════════════════════════════════════════════════════════════ */
(function buildLegend() {
  const el = $("#legend");
  planes.forEach((p, i) => {
    const row = document.createElement("div"); row.className = "legrow";
    row.innerHTML =
      `<span class="swatch" style="color:${p.accent};background:${p.accent}"></span>` +
      `<span class="ln">${p.num} · ${p.title}</span>` +
      `<span class="lc">${(p.cards || []).length}</span>`;
    row.addEventListener("click", () => focusPlane(i));
    el.appendChild(row);
  });
})();

/* ════════════════════════════════════════════════════════════════════════
 * Pipeline narration / build animation
 * ════════════════════════════════════════════════════════════════════════ */
const pipeline = DATA.pipeline || [];
let playing = false;
const gateNames = (planes[2] && planes[2].strip) || ["Planning", "Build", "Review", "Test", "Security", "Release", "Owner Approval", "Rollback"];

function setNarration(stageNo, total, title, desc, accent) {
  $("#pStage").textContent = total ? `Stage ${stageNo} / ${total}` : "Idle";
  if (accent) $("#pStage").style.color = accent;
  $("#pTitle").textContent = title;
  $("#pDesc").textContent = desc;
  $("#pFill").style.width = total ? `${Math.round((stageNo / total) * 100)}%` : "0%";
}
function resetGatePips() {
  const g = $("#gatepips"); g.innerHTML = "";
  gateNames.forEach((n) => { const s = document.createElement("span"); s.className = "pip"; s.textContent = n; s.dataset.k = n; g.appendChild(s); });
}
resetGatePips();

async function lightGatesSequentially() {
  const pips = [...document.querySelectorAll("#gatepips .pip")];
  for (const pip of pips) { pip.classList.add("lit"); await sleep(260); if (!playing) return; }
}

async function playBuild() {
  if (playing) return;
  playing = true;
  $("#btnPlay").textContent = "■ Stop build";
  $("#detail").classList.remove("show");
  prodGroup.visible = false; product.scale.setScalar(0.001); prodGroup.children[1].material.opacity = 0;
  resetGatePips();
  packet.visible = true; packet.position.y = coreY; packetGoalY = coreY; packetLight.intensity = 2.2;

  const total = pipeline.length;
  for (let s = 0; s < total; s++) {
    if (!playing) break;
    const stage = pipeline[s];
    const pr = planeRecords[stage.plane] || planeRecords[0];
    setNarration(s + 1, total, stage.title, stage.desc, pr.data.accent);
    // move the packet to this plane and frame it
    packetGoalY = pr.y;
    rig.flyTo(new THREE.Vector3(0, pr.y, 0), pr.ringR * 2.4 + 140, 1.16, pr.group.rotation.y + 0.6, 1.3);
    pulsePlane(stage.plane, 2.2);
    await sleep(900);
    if (!playing) break;
    if (stage.gates) await lightGatesSequentially();
    await sleep(stage.gates ? 700 : 1500);
  }

  if (playing) {
    // reveal the finished product
    setNarration(total, total, "Build complete", "From a single prompt to a bounded, grounded, verified and audited pull request — leaving no work undone.", "#2fd07a");
    packetGoalY = prodY; prodGroup.visible = true;
    rig.flyTo(new THREE.Vector3(0, prodY + 10, 0), 320, 1.18, 0.5, 1.4);
    const t0 = performance.now();
    await new Promise((res) => {
      const grow = () => {
        const k = clamp((performance.now() - t0) / 1100, 0, 1); const e = easeInOutCubic(k);
        product.scale.setScalar(0.001 + e); prodGroup.children[1].material.opacity = 0.6 * e;
        if (k < 1 && playing) requestAnimationFrame(grow); else res();
      };
      grow();
    });
    burst(prodGroup, 0x66ffb0);
    await sleep(1400);
  }
  // wind down
  playing = false;
  packetLight.intensity = 0; packet.visible = false;
  $("#btnPlay").textContent = "▶ Play the build";
  setNarration(0, 0, "Press “Play the build” to watch a prompt become a finished product", "The glowing packet travels the full path — surface → operating layer → the eight gates → orchestration → cognition → verification → a shipped pull request.");
  $("#pFill").style.width = "100%";
}

function stopBuild() {
  playing = false; packet.visible = false; packetLight.intensity = 0;
  $("#btnPlay").textContent = "▶ Play the build";
}

/* particle burst */
const bursts = [];
function burst(parent, color) {
  const M = 160; const pos = new Float32Array(M * 3); const vel = [];
  for (let i = 0; i < M; i++) {
    pos[i * 3] = pos[i * 3 + 1] = pos[i * 3 + 2] = 0;
    const dir = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize().multiplyScalar(60 + Math.random() * 120);
    vel.push(dir);
  }
  const g = new THREE.BufferGeometry(); g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  const pts = new THREE.Points(g, new THREE.PointsMaterial({ color, size: 4.5, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false }));
  parent.add(pts); bursts.push({ pts, vel, t: 0 });
}

/* ════════════════════════════════════════════════════════════════════════
 * UI wiring
 * ════════════════════════════════════════════════════════════════════════ */
let autorotate = true, labelsOn = true;
$("#btnPlay").addEventListener("click", () => (playing ? stopBuild() : playBuild()));
$("#btnReset").addEventListener("click", resetView);
$("#btnOverview").addEventListener("click", resetView);
$("#btnRotate").addEventListener("click", (e) => { autorotate = !autorotate; e.target.classList.toggle("on", autorotate); });
$("#btnLabels").addEventListener("click", (e) => { labelsOn = !labelsOn; e.target.classList.toggle("on", labelsOn); labelSprites.forEach((l) => (l.visible = labelsOn)); });

window.addEventListener("keydown", (e) => {
  if (e.key === " ") { e.preventDefault(); playing ? stopBuild() : playBuild(); }
  else if (e.key === "r" || e.key === "R") resetView();
  else if (e.key === "Escape") $("#detail").classList.remove("show");
});

function resize() {
  const w = window.innerWidth, h = window.innerHeight;
  camera.aspect = w / h; camera.updateProjectionMatrix();
  renderer.setSize(w, h); renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2.5));
}
window.addEventListener("resize", resize);

/* ════════════════════════════════════════════════════════════════════════
 * Animation loop
 * ════════════════════════════════════════════════════════════════════════ */
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(0.05, clock.getDelta());
  const t = clock.elapsedTime;

  if (autorotate && rig.idle() && !rig.tween) rig.goal.theta += dt * 0.05;
  rig.update(dt);

  // core + product spin/pulse
  core.rotation.y += dt * 0.3; core.rotation.x += dt * 0.12;
  coreRing.rotation.z += dt * 0.25;
  const cp = 1 + Math.sin(t * 1.6) * 0.06; core.scale.setScalar(cp);
  product.rotation.y += dt * 0.6; product.rotation.x += dt * 0.2;

  // node idle shimmer
  for (const u of nodeMeshes) { u.rotation.y += dt * 0.5; }

  // packet travel
  if (packet.visible) {
    packet.position.y += (packetGoalY - packet.position.y) * (1 - Math.exp(-dt * 3.2));
    packet.position.x = Math.sin(t * 2.0) * 4; packet.position.z = Math.cos(t * 2.0) * 4;
    packetCore.rotation.y += dt * 3;
  }

  // flowing spine particles (descending)
  const fp = flowGeo.attributes.position.array;
  for (let i = 0; i < FLOW_N; i++) {
    let y = fp[i * 3 + 1] - dt * (38 + flowSeed[i] * 50);
    if (y < -towerH / 2) y = towerH / 2;
    fp[i * 3 + 1] = y;
  }
  flowGeo.attributes.position.needsUpdate = true;

  // plane pulses
  for (let i = pulses.length - 1; i >= 0; i--) {
    const pu = pulses[i]; pu.t += dt;
    const k = Math.max(0, 1 - pu.t / pu.dur);
    const boost = Math.sin(Math.min(1, pu.t / pu.dur) * Math.PI) * k;
    pu.pr.ring.material.opacity = 0.5 + boost * 0.5;
    pu.pr.ringGlow.material.opacity = 0.12 + boost * 0.45;
    pu.pr.hub.material.emissiveIntensity = 1.1 + boost * 1.8;
    pu.pr.nodes.forEach((u) => { u.glow.material.opacity = 0.5 + boost * 0.45; u.mat.emissiveIntensity = u.baseEmissive + boost * 1.6; });
    if (pu.t >= pu.dur) {
      pu.pr.ring.material.opacity = 0.5; pu.pr.ringGlow.material.opacity = 0.12; pu.pr.hub.material.emissiveIntensity = 1.1;
      pu.pr.nodes.forEach((u) => { u.glow.material.opacity = 0.5; u.mat.emissiveIntensity = u.baseEmissive; });
      pulses.splice(i, 1);
    }
  }

  // hover emphasis
  for (const u of nodeMeshes) {
    const want = (hovered === u) ? u.userData.baseScale * 1.55 : u.userData.baseScale;
    u.scale.x += (want - u.scale.x) * (1 - Math.exp(-dt * 12));
    u.scale.y = u.scale.z = u.scale.x;
  }

  // bursts
  for (let i = bursts.length - 1; i >= 0; i--) {
    const b = bursts[i]; b.t += dt; const arr = b.pts.geometry.attributes.position.array;
    for (let j = 0; j < b.vel.length; j++) {
      arr[j * 3] += b.vel[j].x * dt; arr[j * 3 + 1] += b.vel[j].y * dt; arr[j * 3 + 2] += b.vel[j].z * dt;
    }
    b.pts.geometry.attributes.position.needsUpdate = true;
    b.pts.material.opacity = Math.max(0, 1 - b.t / 1.6);
    if (b.t > 1.6) { b.pts.parent.remove(b.pts); bursts.splice(i, 1); }
  }

  renderer.render(scene, camera);
}

/* boot */
resetView();
animate();
setTimeout(() => $("#loader").classList.add("gone"), 350);

// expose a tiny API for debugging / external embedding
window.MUSE_ATLAS = { focusPlane, resetView, playBuild, stopBuild, scene };
